WITH sales_agg AS (SELECT ss_customer_sk, ss_sold_date_sk, SUM(ss_net_profit) AS total_net_profit, SUM(ss_ext_sales_price) AS total_sales, SUM(ss_quantity) AS total_quantity FROM store_sales GROUP BY ss_customer_sk, ss_sold_date_sk), returns_agg AS (SELECT wr_refunded_customer_sk AS customer_sk, SUM(wr_return_amt_inc_tax) AS total_return_amount, SUM(wr_net_loss) AS total_net_loss FROM web_returns GROUP BY wr_refunded_customer_sk), top_reason_per_customer_agg AS (SELECT wr_refunded_customer_sk AS customer_sk, wr_reason_sk, SUM(wr_return_amt_inc_tax) AS reason_return_amount FROM web_returns GROUP BY wr_refunded_customer_sk, wr_reason_sk), top_reason_per_customer AS (SELECT customer_sk, wr_reason_sk, reason_return_amount, ROW_NUMBER() OVER (PARTITION BY customer_sk ORDER BY reason_return_amount DESC) AS rn FROM top_reason_per_customer_agg) SELECT * FROM (SELECT c.c_customer_id, s.ss_sold_date_sk, s.total_net_profit, COALESCE(r.total_return_amount, 0) AS total_return_amount, COALESCE(r.total_net_loss, 0) AS total_net_loss, COALESCE(rt.r_reason_desc, 'No Returns') AS top_return_reason, CASE WHEN s.total_net_profit > 1000 THEN 'High' WHEN s.total_net_profit > 0 THEN 'Medium' ELSE 'Low' END AS profit_category, RANK() OVER (PARTITION BY s.ss_sold_date_sk ORDER BY s.total_net_profit DESC) AS profit_rank FROM sales_agg s LEFT JOIN returns_agg r ON s.ss_customer_sk = r.customer_sk LEFT JOIN (SELECT customer_sk, wr_reason_sk FROM top_reason_per_customer WHERE rn = 1) tr ON s.ss_customer_sk = tr.customer_sk LEFT JOIN reason rt ON tr.wr_reason_sk = rt.r_reason_sk JOIN customer c ON s.ss_customer_sk = c.c_customer_sk) t WHERE profit_rank <= 5 ORDER BY ss_sold_date_sk, profit_rank
